import{_ as o,C as a,o as e,c as s,a5 as r,E as n}from"./chunks/framework.DuVjalqf.js";const i="/rb_cobot_docs_muscat/images/move-menu/workspace-editor-overview.avif",l="/rb_cobot_docs_muscat/images/move-menu/workspace-editor-controls.avif",h="/rb_cobot_docs_muscat/images/move-menu/workspace-editor-properties.avif",g="/rb_cobot_docs_muscat/images/move-menu/workspace-editor-selection.avif",k=JSON.parse('{"title":"워크스페이스 편집 화면","description":"","frontmatter":{"title":"워크스페이스 편집 화면"},"headers":[],"relativePath":"manual/move-menu/workspace-editor.md","filePath":"manual/move-menu/workspace-editor.md","lastUpdated":1792552919000}'),c={name:"manual/move-menu/workspace-editor.md"};function p(m,t,b,_,u,v){const d=a("DemoFrame");return e(),s("div",null,[t[0]||(t[0]=r('<h1 id="워크스페이스-편집-화면" tabindex="-1">워크스페이스 편집 화면 <a class="header-anchor" href="#워크스페이스-편집-화면" aria-label="Permalink to &quot;워크스페이스 편집 화면&quot;">​</a></h1><p>워크스페이스를 만들거나 불러오면 이름·저장 버튼, 오브젝트 목록, 속성 입력 영역이 나타납니다. 이 페이지에서는 <strong>워크스페이스 전체 관리</strong>, <strong>오브젝트 선택·관리</strong>, <strong>선택한 오브젝트 편집</strong>을 구분해 설명합니다.</p><p>새로 만들기와 불러오기, 작업대 배치 예제는 <a href="./workspace">워크스페이스 사용 방법</a>을 참고하세요.</p><h2 id="열린-화면의-구성" tabindex="-1">열린 화면의 구성 <a class="header-anchor" href="#열린-화면의-구성" aria-label="Permalink to &quot;열린 화면의 구성&quot;">​</a></h2><p>다음은 <strong>베이스 탭</strong>에서 <code>demo_cell</code>을 만들고 직육면체와 원기둥을 추가한 뒤, 직육면체 하나를 선택한 상태입니다. 새 워크스페이스를 만들기만 했다면 목록은 비어 있으며, 오브젝트를 선택하기 전에는 속성 대신 선택 안내가 표시됩니다.</p><p><img src="'+i+'" alt="오브젝트를 선택한 워크스페이스 편집 화면"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th>번호</th><th>영역</th><th>역할</th></tr></thead><tbody><tr><td>①</td><td>워크스페이스 관리</td><td>이름·저장 상태 확인, 되돌리기·다시 실행, 전체 관리 메뉴, 닫기·저장</td></tr><tr><td>②</td><td>오브젝트 리스트</td><td>도형·파일 추가, 편집할 항목 선택, 이름 변경·숨기기·삭제</td></tr><tr><td>③</td><td>오브젝트 속성</td><td>선택한 항목의 위치·회전·크기를 수치로 편집</td></tr><tr><td>④</td><td>3D 편집 도구</td><td>위치·회전·크기 중 3D 화면에서 조작할 도구 선택</td></tr></tbody></table></div><p><strong>베이스</strong>는 로봇 주변 물체를, <strong>툴</strong>은 툴에 부착할 물체를 구성합니다. 툴이 여러 개인 로봇에서는 툴별 탭이 나뉩니다. 편집할 대상에 맞는 탭을 먼저 선택합니다.</p><h2 id="상단-관리-영역과-목록-1·2" tabindex="-1">상단 관리 영역과 목록(①·②) <a class="header-anchor" href="#상단-관리-영역과-목록-1·2" aria-label="Permalink to &quot;상단 관리 영역과 목록(①·②)&quot;">​</a></h2><p>아래 이미지는 <strong>오브젝트 추가(⑪)를 펼친 상태</strong>입니다. ×는 추가 항목을 접는 버튼이며, 워크스페이스를 닫는 <strong>닫기</strong>(⑧)와 다릅니다.</p><p><img src="'+l+'" alt="워크스페이스 이름과 관리 버튼 및 오브젝트 목록"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th>번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>⑤</td><td>이름·저장 상태</td><td>현재 워크스페이스 이름을 표시합니다. 이름을 더블클릭하거나 ⑦의 <strong>이름 변경</strong>을 선택해 수정합니다. Enter로 확정하고 Esc로 취소합니다.</td></tr><tr><td>⑥</td><td>되돌리기·다시 실행</td><td>왼쪽 화살표는 직전 편집을 되돌리고, 오른쪽 화살표는 되돌린 편집을 다시 적용합니다. 해당 이력이 없으면 비활성화됩니다.</td></tr><tr><td>⑦</td><td>워크스페이스 메뉴</td><td>현재 워크스페이스 전체를 관리하는 메뉴를 엽니다. 개별 항목의 메뉴(⑫)와 구분합니다.</td></tr><tr><td>⑧</td><td>닫기</td><td>편집 중인 워크스페이스를 닫습니다. 저장되지 않은 변경이 있으면 확인 창이 표시됩니다.</td></tr><tr><td>⑨</td><td>저장</td><td>현재 변경 내용을 즉시 저장합니다. 저장 중이거나 저장할 변경이 없으면 비활성화됩니다.</td></tr><tr><td>⑩</td><td>선택</td><td>여러 항목을 체크하는 모드로 전환합니다. 모드가 켜지면 <strong>선택 취소</strong>로 표시됩니다.</td></tr><tr><td>⑪</td><td>오브젝트 추가</td><td>+를 눌러 도형·파일 추가 항목을 펼치고, ×를 눌러 접습니다.</td></tr><tr><td>⑫</td><td>오브젝트 메뉴</td><td>해당 항목의 이름 변경, 씬에서 숨기기·다시 표시, 오브젝트 삭제를 선택합니다.</td></tr></tbody></table></div><h3 id="이름-옆의-저장-표시-5" tabindex="-1">이름 옆의 저장 표시(⑤) <a class="header-anchor" href="#이름-옆의-저장-표시-5" aria-label="Permalink to &quot;이름 옆의 저장 표시(⑤)&quot;">​</a></h3><p>편집 내용은 자동저장됩니다. <strong>저장 안 됨</strong>은 아직 저장되지 않은 변경이 있다는 뜻입니다. 저장이 끝나면 <strong>저장됨</strong>이 잠시 표시된 뒤 사라집니다. <strong>저장됨 표시가 사라졌다는 이유만으로 미저장 상태인 것은 아닙니다.</strong> 되돌리기·다시 실행으로 정한 최종 상태는 저장 버튼으로 저장할 수 있습니다.</p><h3 id="워크스페이스-메뉴-7" tabindex="-1">워크스페이스 메뉴(⑦) <a class="header-anchor" href="#워크스페이스-메뉴-7" aria-label="Permalink to &quot;워크스페이스 메뉴(⑦)&quot;">​</a></h3><div class="tbl-nowrap-1"><table tabindex="0"><thead><tr><th>메뉴</th><th>동작·사용 조건</th></tr></thead><tbody><tr><td>새로 만들기</td><td>새 이름으로 빈 워크스페이스를 만듭니다.</td></tr><tr><td>불러오기</td><td>저장된 워크스페이스를 선택해 엽니다. 미저장 변경이 있으면 다른 구성을 열기 전에 확인합니다.</td></tr><tr><td>이름 변경</td><td>현재 워크스페이스의 이름을 수정합니다.</td></tr><tr><td>사본 만들기</td><td>현재 구성을 다른 이름으로 복사합니다. 항목이 없거나 저장 중이면 비활성화됩니다.</td></tr><tr><td>삭제</td><td>확인 후 현재 워크스페이스의 저장된 오브젝트를 삭제합니다. 개별 도형 삭제와 구분합니다.</td></tr><tr><td>오브젝트 전체 삭제</td><td>현재 편집 목록의 모든 항목을 비웁니다. 항목이 없으면 비활성화됩니다.</td></tr><tr><td>마지막 저장 상태로 되돌리기</td><td>미저장 변경을 버리고 마지막 저장 상태를 불러옵니다. 미저장 변경이 없으면 비활성화됩니다. 자동저장 후에는 그 저장 상태가 기준입니다.</td></tr></tbody></table></div><h3 id="추가-항목과-개별-선택-11·12" tabindex="-1">추가 항목과 개별 선택(⑪·⑫) <a class="header-anchor" href="#추가-항목과-개별-선택-11·12" aria-label="Permalink to &quot;추가 항목과 개별 선택(⑪·⑫)&quot;">​</a></h3><p><strong>직육면체·원기둥·구</strong>는 도형을 추가하고, <strong>불러온 파일</strong>은 3D 파일을 선택하는 창을 엽니다. 도형은 최대 5개, 파일은 한 워크스페이스에 1개를 둘 수 있습니다. 기존 파일이 있으면 교체 여부를 확인합니다. 이 페이지의 실습에서는 파일 업로드를 지원하지 않습니다.</p><p>일반 모드에서 목록의 항목을 누르면 해당 오브젝트가 선택되고 ③에 속성이 표시됩니다. <strong>이미 선택한 항목을 다시 누르면 선택이 해제됩니다.</strong> 항목을 더블클릭하거나 ⑫의 <strong>이름 변경</strong>을 선택하면 개별 오브젝트 이름을 수정할 수 있습니다.</p><p>⑫의 <strong>씬에서 숨기기</strong>는 목록에 항목을 남겨 둔 채 3D 화면에서만 가립니다. 숨긴 항목은 목록에서 흐리게 표시되고 숨김 아이콘이 붙습니다. 같은 메뉴의 <strong>씬에 다시 표시</strong>로 복원합니다. <strong>오브젝트 삭제</strong>는 목록과 3D 화면에서 항목을 제거합니다.</p><p>목록의 로딩 아이콘은 불러오는 중임을, 경고 아이콘은 <strong>저장 실패</strong> 또는 <strong>파일을 불러오지 못한 상태</strong>를 나타냅니다.</p><h2 id="속성-입력-영역-3" tabindex="-1">속성 입력 영역(③) <a class="header-anchor" href="#속성-입력-영역-3" aria-label="Permalink to &quot;속성 입력 영역(③)&quot;">​</a></h2><p>다음은 <strong>도형 하나를 선택한 상태</strong>입니다. 위치·회전·크기는 함께 표시되며, 3D 편집 도구(④)의 선택과 관계없이 수치로 입력할 수 있습니다.</p><p><img src="'+h+'" alt="위치 회전 크기 입력과 초기화"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th>번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>⑬</td><td>위치 X·Y·Z</td><td>각 축 방향의 위치를 <strong>mm</strong>로 입력합니다.</td></tr><tr><td>⑭</td><td>회전 RX·RY·RZ</td><td>각 축의 회전 값을 <strong>° 단위</strong>로 입력합니다.</td></tr><tr><td>⑮</td><td>크기 SX·SY·SZ</td><td>도형의 각 방향 치수를 <strong>mm</strong>로 입력합니다. 배율을 입력하는 칸이 아닙니다. 불러온 파일에는 크기 입력이 표시되지 않습니다.</td></tr><tr><td>⑯</td><td>초기화</td><td>선택한 항목의 위치·회전을 0으로 되돌립니다. 도형 크기는 기본 치수로 되돌립니다. 이름이나 다른 항목은 초기화하지 않습니다.</td></tr></tbody></table></div><p>입력칸을 누르면 숫자 키패드가 열립니다. 키패드에서는 <strong>Set</strong>, 키보드에서는 <strong>Enter</strong>로 값을 적용합니다. 입력칸 양옆의 <strong>−·+</strong> 버튼으로 위치·크기를 1mm, 회전을 0.1°씩 조정합니다. 입력 중 키보드의 ↑·↓ 키로도 같은 단위로 조정할 수 있습니다.</p><h2 id="_3d-편집-도구-4" tabindex="-1">3D 편집 도구(④) <a class="header-anchor" href="#_3d-편집-도구-4" aria-label="Permalink to &quot;3D 편집 도구(④)&quot;">​</a></h2><p>오브젝트를 <strong>하나 선택하면 3D 화면 왼쪽</strong>에 도구가 나타납니다. 여기서 고른 모드는 3D 화면의 조작 핸들(기즈모)에 적용됩니다.</p><div class="tbl-nowrap-1"><table tabindex="0"><thead><tr><th>도구</th><th>3D 화면에서 하는 작업</th></tr></thead><tbody><tr><td>위치</td><td>이동 핸들을 끌어 선택한 오브젝트의 위치를 바꿉니다.</td></tr><tr><td>회전</td><td>회전 핸들을 끌어 오브젝트의 방향을 바꿉니다.</td></tr><tr><td>크기</td><td>크기 핸들을 끌어 도형의 치수를 바꿉니다. 불러온 파일에는 이 도구가 표시되지 않습니다.</td></tr></tbody></table></div><p>여러 항목을 체크하는 선택 모드에서는 이 도구가 표시되지 않습니다. 위치·방향·크기를 정확한 값으로 맞추려면 ③의 수치 입력을 사용합니다.</p><h2 id="여러-항목을-관리하는-선택-모드-10" tabindex="-1">여러 항목을 관리하는 선택 모드(⑩) <a class="header-anchor" href="#여러-항목을-관리하는-선택-모드-10" aria-label="Permalink to &quot;여러 항목을 관리하는 선택 모드(⑩)&quot;">​</a></h2><p><strong>선택</strong>을 누르면 각 항목에 체크박스가 나타납니다. 아래는 두 항목 중 하나를 체크한 상태입니다.</p><p><img src="'+g+'" alt="오브젝트 선택 모드의 체크 목록과 일괄 작업"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th>번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>⑰</td><td>체크 목록</td><td>항목을 눌러 체크하거나 해제합니다. 일반 모드의 단일 편집 대상 선택과 구분합니다.</td></tr><tr><td>⑱</td><td>선택 수·일괄 작업</td><td>체크한 수와 <strong>숨기기 N</strong>, <strong>삭제 N</strong> 버튼을 표시합니다. 아무것도 체크하지 않으면 버튼이 비활성화됩니다.</td></tr></tbody></table></div><p><strong>숨기기 N</strong>은 체크한 항목을 씬에서 숨기고, <strong>삭제 N</strong>은 체크한 항목을 삭제합니다. 작업을 적용하면 선택 모드가 종료됩니다. 작업 없이 나가려면 <strong>선택 취소</strong>를 누릅니다.</p><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2><p>편집 기능은 <a href="./workspace#직접-해-보기">워크스페이스</a>의 실습에서 하나씩 연습합니다. 아래 <strong>자유 실습</strong>은 <code>Welding cell</code>이 열려 있는 상태로 시작하며, 이 페이지의 메뉴와 선택 모드를 사용해 볼 수 있습니다.</p>',37)),n(d,{id:"move-menu-workspace-free"}),t[1]||(t[1]=r('<h2 id="간단한-사용-예시" tabindex="-1">간단한 사용 예시 <a class="header-anchor" href="#간단한-사용-예시" aria-label="Permalink to &quot;간단한 사용 예시&quot;">​</a></h2><ol><li>일반 모드에서 편집할 도형 하나를 선택합니다. ③에 속성이 나타나고 ④에 3D 편집 도구가 보입니다.</li><li>위치 X(⑬)에 <code>500</code>을 입력하고 <strong>Set</strong>을 누릅니다. 3D 화면에서 도형의 위치가 바뀌는지 확인합니다.</li><li>다른 도형도 함께 숨기려면 <strong>선택</strong>(⑩)을 누르고 원하는 항목을 체크한 뒤 <strong>숨기기 N</strong>(⑱)을 누릅니다.</li><li>다시 표시할 때는 일반 모드에서 각 항목의 <strong>⋮(⑫) → 씬에 다시 표시</strong>를 사용합니다.</li></ol><p>여러 도형의 위치·크기를 입력하고 저장 후 다시 여는 전체 예제는 <a href="./workspace#예제-작업대와-원기둥-만들기">작업대와 원기둥 만들기</a>로 이어집니다.</p>',3))])}const q=o(c,[["render",p]]);export{k as __pageData,q as default};
